import{St as e,at as t,et as n,it as r,n as i,ot as a,rt as o,vt as s}from"./chunks/framework.CoUqiBXn.js";var c=JSON.parse(`{"title":"Security Considerations","description":"","frontmatter":{},"headers":[],"relativePath":"insights/security-considerations.md","filePath":"insights/security-considerations.md","lastUpdated":1782829006000}`),l={name:`insights/security-considerations.md`},u={class:`info custom-block`},d={class:`custom-block-title`};function f(i,c,l,f,p,m){let h=e(`BadgeCloud`),g=e(`BadgeSelfHosted`),_=e(`DocBadge`);return s(),o(`div`,null,[c[2]||=n(`h1`,{id:`security-considerations`,tabindex:`-1`},[t(`Security Considerations `),n(`a`,{class:`header-anchor`,href:`#security-considerations`,"aria-label":`Permalink to “Security Considerations”`},`​`)],-1),c[3]||=n(`h2`,{id:`template-injection`,tabindex:`-1`},[t(`Template Injection `),n(`a`,{class:`header-anchor`,href:`#template-injection`,"aria-label":`Permalink to “Template Injection”`},`​`)],-1),c[4]||=n(`p`,null,`SysReptor uses server-side rendering for generating PDF reports. This allows template injection attackers.`,-1),c[5]||=n(`p`,null,`This is intentional.`,-1),c[6]||=n(`p`,null,`The template injection is sandboxed in a dedicated Chromium process. Chromium is running in offline mode. It has no possibility to connect to remote locations. It requires an exploit in the Chromium browser to get access to the container.`,-1),a(h),c[7]||=t(),c[8]||=n(`p`,null,[t(`The Chromium process in our cloud is isolated in a dedicated Kubernetes pod. It receives rendering jobs via RabbitMQ, completes its rendering process and shuts down. An attacker breaking out of the Chromium process could prevent it from shutting down until a defined timeout. However, it would `),n(`strong`,null,`not`),t(` be able to receive further rendering jobs.`)],-1),a(g),c[9]||=r(` <p>The Chromium process in self-hosted environments runs in an isolated process in the web application&#39;s docker container by default. An attacker breaking out of the Chromium process can also compromise the web application. However, it is possible to outsource the rendering process into a dedicated docker container. This requires two additional docker containers: Chromium and RabbitMQ. However, the Chromium process will be able to receive further rendering jobs (in contrast to the cloud setup).<br> For resource reasons, we do not use this setup in the standard installation.</p><h2 id="denial-of-service-dos" tabindex="-1">Denial of Service (DoS) <a class="header-anchor" href="#denial-of-service-dos" aria-label="Permalink to “Denial of Service (DoS)”">​</a></h2><p>PDF rendering is a long-running and resource intensive process. Especially WeasyPrint can sometimes be slow when rendering long and complex reports.</p><p>Attackers can inject long-running instructions (via Vue, HTML or CSS) in templates. This might cause DoS of the rendering process.<br> A timeout cancels the Vue template rendering process as soon as rendering time reaches a certain threshold.</p><p>DoS prevention is currently not implemented for WeasyPrint. For now, we accept the risk of DoS in WeasyPrint, since we do not want to prevent rendering long and complex reports which might take some time and system resources.</p><p>This behavior might change in the future.</p><h2 id="server-side-request-forgery-prevention" tabindex="-1">Server-Side Request Forgery Prevention <a class="header-anchor" href="#server-side-request-forgery-prevention" aria-label="Permalink to “Server-Side Request Forgery Prevention”">​</a></h2><p>All Requests to external systems from within the rendering workflow are blocked. This prevents data exfiltration to external systems if attackers inject templates or if there are vulnerabilities in third-party JS libraries.</p><p>This is ensured by two measures:</p><ol><li>The headless Chromium instances uses the offline mode. This simulates that the browser is offline and blocks all outgoing requests.</li><li>For WeasyPrint, we use a custom URL fetcher. This prevents requests to external systems. It allows <code>data:</code>-URLs and access to files uploaded to SysReptor (designer assets, images) only. No HTTP requests are involved when including these resources (neither to localhost), but a custom handler that returns the resources as data following the <a href="https://doc.courtbouillon.org/weasyprint/stable/first_steps.html#security" target="_blank" rel="noreferrer">WeasyPrint security recommendations</a>.</li></ol>`,11),n(`div`,u,[n(`p`,d,[a(_,{icon:`mdi:shield-alert`,label:`Report a security issue`})]),c[0]||=n(`p`,null,[t(`Discovered a security vulnerability?`),n(`br`),t(` Report it responsibly through our vulnerability disclosure process.`)],-1),c[1]||=n(`p`,null,[n(`a`,{href:`https://github.com/Syslifters/sysreptor/security`,target:`_blank`,rel:`noreferrer`},`Disclose responsibly`)],-1)])])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};